1	package reasoning
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strconv"
7		"strings"
8	
9		"gopkg.in/yaml.v3"
10	)
11	
12	// Reasoning is the canonical scalar for model-side reasoning controls.
13	type Reasoning string
14	
15	const (
16		ReasoningAuto    Reasoning = "auto"
17		ReasoningOff     Reasoning = "off"
18		ReasoningLow     Reasoning = "low"
19		ReasoningMedium  Reasoning = "medium"
20		ReasoningHigh    Reasoning = "high"
21		ReasoningMinimal Reasoning = "minimal"
22		ReasoningXHigh   Reasoning = "xhigh"
23		ReasoningMax     Reasoning = "max"
24	)
25	
26	// PortableBudgets are fallback named reasoning token budgets.
27	var PortableBudgets = map[Reasoning]int{
28		ReasoningOff:    0,
29		ReasoningLow:    2048,
30		ReasoningMedium: 8192,
31		ReasoningHigh:   32768,
32	}
33	
34	// ReasoningTokens returns a numeric reasoning-token request.
35	func ReasoningTokens(n int) Reasoning {
36		return Reasoning(strconv.Itoa(n))
37	}
38	
39	type Kind string
40	
41	const (
42		KindUnset  Kind = "unset"
43		KindAuto   Kind = "auto"
44		KindOff    Kind = "off"
45		KindNamed  Kind = "named"
46		KindTokens Kind = "tokens"
47	)
48	
49	type Policy struct {
50		Kind   Kind
51		Value  Reasoning
52		Tokens int
53	}
54	
55	func (p Policy) IsSet() bool {
56		return p.Kind != KindUnset
57	}
58	
59	func (p Policy) IsExplicitOff() bool {
60		return p.Kind == KindOff || (p.Kind == KindTokens && p.Tokens == 0)
61	}
62	
63	func Normalize(value string) (Reasoning, error) {
64		p, err := ParseString(value)
65		if err != nil {
66			return "", err
67		}
68		return p.Value, nil
69	}
70	
71	func ParseString(value string) (Policy, error) {
72		s := strings.ToLower(strings.TrimSpace(value))
73		if s == "" {
74			return Policy{Kind: KindUnset}, nil
75		}
76		switch s {
77		case "auto":
78			return Policy{Kind: KindAuto, Value: ReasoningAuto}, nil
79		case "off", "none", "false":
80			return Policy{Kind: KindOff, Value: ReasoningOff}, nil
81		case "low":
82			return Policy{Kind: KindNamed, Value: ReasoningLow}, nil
83		case "medium":
84			return Policy{Kind: KindNamed, Value: ReasoningMedium}, nil
85		case "high":
86			return Policy{Kind: KindNamed, Value: ReasoningHigh}, nil
87		case "minimal":
88			return Policy{Kind: KindNamed, Value: ReasoningMinimal}, nil
89		case "x-high", "x_high", "xhigh":
90			return Policy{Kind: KindNamed, Value: ReasoningXHigh}, nil
91		case "max":
92			return Policy{Kind: KindNamed, Value: ReasoningMax}, nil
93		}
94		tokens, err := strconv.Atoi(s)
95		if err == nil {
96			if tokens < 0 {
97				return Policy{}, fmt.Errorf("reasoning: negative token budget %d is invalid", tokens)
98			}
99			if tokens == 0 {
100				return Policy{Kind: KindOff, Value: ReasoningOff, Tokens: 0}, nil
101			}
102			return Policy{Kind: KindTokens, Value: ReasoningTokens(tokens), Tokens: tokens}, nil
103		}
104		return Policy{}, fmt.Errorf("reasoning: unsupported value %q", value)
105	}
106	
107	func Parse(value any) (Policy, error) {
108		switch v := value.(type) {
109		case nil:
110			return Policy{Kind: KindUnset}, nil
111		case Reasoning:
112			return ParseString(string(v))
113		case string:
114			return ParseString(v)
115		case int:
116			return ParseString(strconv.Itoa(v))
117		case int64:
118			return ParseString(strconv.FormatInt(v, 10))
119		case float64:
120			if v != float64(int(v)) {
121				return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
122			}
123			return ParseString(strconv.Itoa(int(v)))
124		case json.Number:
125			i, err := strconv.Atoi(v.String())
126			if err != nil {
127				return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
128			}
129			return ParseString(strconv.Itoa(i))
130		default:
131			return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
132		}
133	}
134	
135	func BudgetFor(policy Policy, budgets map[Reasoning]int, maxTokens int) (int, error) {
136		switch policy.Kind {
137		case KindUnset, KindAuto:
138			return 0, nil
139		case KindOff:
140			return 0, nil
141		case KindTokens:
142			if maxTokens > 0 && policy.Tokens > maxTokens {
143				return 0, fmt.Errorf("reasoning: token budget %d exceeds maximum %d", policy.Tokens, maxTokens)
144			}
145			return policy.Tokens, nil
146		case KindNamed:
147			if policy.Value == ReasoningMax {
148				if maxTokens <= 0 {
149					return 0, fmt.Errorf("reasoning: max requires a known model/provider maximum")
150				}
151				return maxTokens, nil
152			}
153			if budgets != nil {
154				if budget, ok := budgets[policy.Value]; ok {
155					return budget, nil
156				}
157			}
158			if budget, ok := PortableBudgets[policy.Value]; ok {
159				if maxTokens > 0 && budget > maxTokens {
160					return 0, fmt.Errorf("reasoning: %s budget %d exceeds maximum %d", policy.Value, budget, maxTokens)
161				}
162				return budget, nil
163			}
164			return 0, fmt.Errorf("reasoning: unsupported named value %q for numeric budget", policy.Value)
165		default:
166			return 0, fmt.Errorf("reasoning: unsupported policy kind %q", policy.Kind)
167		}
168	}
169	
170	func (r *Reasoning) UnmarshalJSON(data []byte) error {
171		var s string
172		if err := json.Unmarshal(data, &s); err == nil {
173			normalized, err := Normalize(s)
174			if err != nil {
175				return err
176			}
177			*r = normalized
178			return nil
179		}
180		var n json.Number
181		if err := json.Unmarshal(data, &n); err == nil {
182			policy, err := Parse(n)
183			if err != nil {
184				return err
185			}
186			*r = policy.Value
187			return nil
188		}
189		return fmt.Errorf("reasoning: JSON value must be a string or integer")
190	}
191	
192	func (r *Reasoning) UnmarshalYAML(value *yaml.Node) error {
193		switch value.Kind {
194		case yaml.ScalarNode:
195			policy, err := ParseString(value.Value)
196			if err != nil {
197				return err
198			}
199			*r = policy.Value
200			return nil
201		default:
202			return fmt.Errorf("reasoning: YAML value must be a scalar")
203		}
204	}
