225	// ChatStream implements agent.StreamingProvider for token-level streaming.
226	func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
227		model, err := p.resolveModel(ctx)
228		if err != nil {
229			return nil, err
230		}
231		if opts.Model != "" {
232			model = opts.Model
233		}
234	
235		reqOpts, err := p.compatRequestOptions(model, opts)
236		if err != nil {
237			return nil, err
238		}
239	
240		return p.client.ChatStream(ctx, model, messages, tools, reqOpts, openaicompat.StreamHooks{
241			Cost: p.costAttribution,
242			Attempt: func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
243				return p.attemptMetadata(model, responseModel, streamAttemptCost(cost))
244			},
245		})
246	}
247	
248	// compatRequestOptions is the canonical openai-compat wire-field assembler
249	// and, per ADR-007 §3, the architectural home for any future
250	// (model_family × reasoning_state × profile) sampling-composition rule.
251	// Reasoning policy and the resolved sampling profile both reach this seam;
252	// when a profile field needs to be clipped or substituted because the
253	// model is in a thinking state (or vice-versa), the rule lives here — not
254	// in the resolver, not in the catalog.
255	//
256	// v1 ships without an active composition rule. The seeded "code" profile
257	// (T=0.6, top_p=0.95, top_k=20) matches Qwen3.x's published thinking-mode
258	// precise-coding recommendation exactly, and is also non-greedy enough to
259	// be safe in the non-thinking-mode case. When a future profile adds a
260	// value that diverges between thinking and non-thinking states for some
261	// family, add the clip rule here; for now, all five sampler fields pass
262	// through unchanged regardless of reasoning state.
263	func (p *Provider) compatRequestOptions(model string, opts agent.Options) (openaicompat.RequestOptions, error) {
264		extra, err := p.reasoningRequestOptions(model, opts)
265		if err != nil {
266			return openaicompat.RequestOptions{}, err
267		}
268		temperature := opts.Temperature
269		topP := opts.TopP
270		if nativeOpenAIUsesDefaultSamplingOnly(p.providerSystem, model) {
271			temperature = nil
272			topP = nil
273		}
274		// Non-standard sampling fields (top_k, min_p, repetition_penalty) ride
275		// as top-level body extras on OpenAI-compatible local/provider wires.
276		// OpenAI proper rejects these as unknown parameters, so only send them
277		// to compatibility providers that are known to accept them.
278		if p.providerSystem != "openai" {
279			if opts.TopK != nil {
280				extra = append(extra, option.WithJSONSet("top_k", *opts.TopK))
281			}
282			if opts.MinP != nil {
283				extra = append(extra, option.WithJSONSet("min_p", *opts.MinP))
284			}
285			if opts.RepetitionPenalty != nil {
286				extra = append(extra, option.WithJSONSet("repetition_penalty", *opts.RepetitionPenalty))
287			}
288		}
289		return openaicompat.RequestOptions{
290			MaxTokens:         opts.MaxTokens,
291			Temperature:       temperature,
292			TopP:              topP,
293			TopK:              opts.TopK,
294			MinP:              opts.MinP,
295			RepetitionPenalty: opts.RepetitionPenalty,
296			Seed:              opts.Seed,
297			Stop:              opts.Stop,
298			ExtraOptions:      extra,
299			CachePolicy:       opts.CachePolicy,
300		}, nil
301	}
302	
303	func nativeOpenAIUsesDefaultSamplingOnly(providerSystem, model string) bool {
304		if providerSystem != "openai" {
305			return false
306		}
307		return strings.HasPrefix(strings.ToLower(model), "gpt-5")
308	}
