310	func (p *Provider) attemptMetadata(requestedModel, responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
311		if cost == nil {
312			cost = &agent.CostAttribution{Source: agent.CostSourceUnknown}
313		}
314		return &agent.AttemptMetadata{
315			ProviderName:   p.providerName,
316			ProviderSystem: p.providerSystem,
317			ServerAddress:  p.serverAddress,
318			ServerPort:     p.serverPort,
319			RequestedModel: requestedModel,
320			ResponseModel:  responseModel,
321			ResolvedModel:  responseModel,
322			Cost:           cost,
323		}
324	}
325	
326	func (p *Provider) costAttribution(rawUsage string) *agent.CostAttribution {
327		if p.usageCost == nil {
328			return nil
329		}
330		cost, _ := p.usageCost(rawUsage)
331		return cost
332	}
333	
334	// reasoningRequestOptions builds per-request options. For thinking models
335	// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
336	// only when the concrete provider declares the matching wire support.
337	func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, error) {
338		policy, err := reasoningpolicy.Parse(opts.Reasoning)
339		if err != nil {
340			return nil, err
341		}
342		explicitRequest := policy.IsSet()
343		if !explicitRequest {
344			policy, err = reasoningpolicy.Parse(p.reasoningDefault)
345			if err != nil {
346				return nil, err
347			}
348		}
349	
350		if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
351			return nil, nil
352		}
353	
354		// Catalog reasoning_wire metadata gates the wire shape before any
355		// provider-specific encoding runs. Models flagged as reasoning_wire=none
356		// have no reasoning surface at all; an explicit non-off request is a
357		// catalog/wire mismatch and must surface as an error rather than be
358		// silently dropped. Models flagged as reasoning_wire=model_id encode the
359		// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
360		// upstream endpoint cannot honor an external reasoning toggle, so the
361		// reasoning field must be stripped from the wire body.
362		switch p.modelReasoningWireFor(model) {
363		case "none":
364			if explicitRequest && !policy.IsExplicitOff() {
365				return nil, fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
366			}
367			return nil, nil
368		case "model_id":
369			return nil, nil
370		}
371	
372		if !p.SupportsThinking() {
373			if policy.IsExplicitOff() {
374				return nil, nil
375			}
376			if explicitRequest {
377				return nil, fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
378			}
379			return nil, nil
380		}
381	
382		if policy.IsExplicitOff() {
383			switch p.thinkingWireFormat() {
384			case ThinkingWireFormatQwen:
385				if !isQwenModel(model) {
386					if explicitRequest && p.strictThinkingModelMatch() {
387						return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
388					}
389					return nil, nil
390				}
391				return []option.RequestOption{
392					option.WithJSONSet("enable_thinking", false),
393					option.WithJSONSet("thinking_budget", 0),
394				}, nil
395			case ThinkingWireFormatOpenRouter:
396				return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
397					"effort": "none",
398				})}, nil
399			}
400			return nil, nil
401		}
402	
403		if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
404			return openRouterReasoningOptions(policy)
405		}
406		if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) {
407			if explicitRequest && p.strictThinkingModelMatch() {
408				return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
409			}
410			return nil, nil
411		}
412	
413		thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
414		if err != nil {
415			return nil, fmt.Errorf("openai: %w", err)
416		}
417		if thinkingBudget <= 0 {
418			return nil, nil
419		}
