63	func Normalize(value string) (Reasoning, error) {
64		p, err := ParseString(value)
65		if err != nil {
66			return "", err
67		}
68		return p.Value, nil
69	}
70	
71	func ParseString(value string) (Policy, error) {
72		s := strings.ToLower(strings.TrimSpace(value))
73		if s == "" {
74			return Policy{Kind: KindUnset}, nil
75		}
76		switch s {
77		case "auto":
78			return Policy{Kind: KindAuto, Value: ReasoningAuto}, nil
79		case "off", "none", "false":
80			return Policy{Kind: KindOff, Value: ReasoningOff}, nil
81		case "low":
82			return Policy{Kind: KindNamed, Value: ReasoningLow}, nil
83		case "medium":
84			return Policy{Kind: KindNamed, Value: ReasoningMedium}, nil
85		case "high":
86			return Policy{Kind: KindNamed, Value: ReasoningHigh}, nil
87		case "minimal":
88			return Policy{Kind: KindNamed, Value: ReasoningMinimal}, nil
89		case "x-high", "x_high", "xhigh":
90			return Policy{Kind: KindNamed, Value: ReasoningXHigh}, nil
91		case "max":
92			return Policy{Kind: KindNamed, Value: ReasoningMax}, nil
93		}
94		tokens, err := strconv.Atoi(s)
95		if err == nil {
96			if tokens < 0 {
97				return Policy{}, fmt.Errorf("reasoning: negative token budget %d is invalid", tokens)
98			}
99			if tokens == 0 {
100				return Policy{Kind: KindOff, Value: ReasoningOff, Tokens: 0}, nil
101			}
102			return Policy{Kind: KindTokens, Value: ReasoningTokens(tokens), Tokens: tokens}, nil
103		}
104		return Policy{}, fmt.Errorf("reasoning: unsupported value %q", value)
105	}
106	
107	func Parse(value any) (Policy, error) {
108		switch v := value.(type) {
109		case nil:
110			return Policy{Kind: KindUnset}, nil
111		case Reasoning:
112			return ParseString(string(v))
113		case string:
114			return ParseString(v)
115		case int:
116			return ParseString(strconv.Itoa(v))
117		case int64:
118			return ParseString(strconv.FormatInt(v, 10))
119		case float64:
120			if v != float64(int(v)) {
121				return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
122			}
123			return ParseString(strconv.Itoa(int(v)))
124		case json.Number:
125			i, err := strconv.Atoi(v.String())
126			if err != nil {
127				return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
128			}
129			return ParseString(strconv.Itoa(i))
130		default:
131			return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
132		}
133	}
