135	func BudgetFor(policy Policy, budgets map[Reasoning]int, maxTokens int) (int, error) {
136		switch policy.Kind {
137		case KindUnset, KindAuto:
138			return 0, nil
139		case KindOff:
140			return 0, nil
141		case KindTokens:
142			if maxTokens > 0 && policy.Tokens > maxTokens {
143				return 0, fmt.Errorf("reasoning: token budget %d exceeds maximum %d", policy.Tokens, maxTokens)
144			}
145			return policy.Tokens, nil
146		case KindNamed:
147			if policy.Value == ReasoningMax {
148				if maxTokens <= 0 {
149					return 0, fmt.Errorf("reasoning: max requires a known model/provider maximum")
150				}
151				return maxTokens, nil
152			}
153			if budgets != nil {
154				if budget, ok := budgets[policy.Value]; ok {
155					return budget, nil
156				}
157			}
158			if budget, ok := PortableBudgets[policy.Value]; ok {
159				if maxTokens > 0 && budget > maxTokens {
160					return 0, fmt.Errorf("reasoning: %s budget %d exceeds maximum %d", policy.Value, budget, maxTokens)
161				}
162				return budget, nil
163			}
164			return 0, fmt.Errorf("reasoning: unsupported named value %q for numeric budget", policy.Value)
165		default:
166			return 0, fmt.Errorf("reasoning: unsupported policy kind %q", policy.Kind)
167		}
168	}
