170	func (r *Reasoning) UnmarshalJSON(data []byte) error {
171		var s string
172		if err := json.Unmarshal(data, &s); err == nil {
173			normalized, err := Normalize(s)
174			if err != nil {
175				return err
176			}
177			*r = normalized
178			return nil
179		}
180		var n json.Number
181		if err := json.Unmarshal(data, &n); err == nil {
182			policy, err := Parse(n)
183			if err != nil {
184				return err
185			}
186			*r = policy.Value
187			return nil
188		}
189		return fmt.Errorf("reasoning: JSON value must be a string or integer")
190	}
